// MOVE 3b (move3-2 .. move3-7), Collins #9: Celles, 23-27 December 1944. Basemap ardennes_hd_ref (z10, HD), winter look (snow until
// the skies clear on Christmas Day, cold grade). Copies the structure of rokossovsky/scenes-src/move3.js:
//   move3-2  wide (option 1, 24 Dec control: the Bulge at its deepest, Bastogne encircled) -> push-in (option 2 glowing fronts):
//            2nd Panzer's spearhead (Luttwitz badge) at Foy-Notre-Dame / Celles, 4-5 MILES from the Dinant bridges, fuel -> OUT OF FUEL
//   move3-2b mid-wide (option 1): VII Corps swings south from Aachen, 2nd + 3rd Armored, 75th + 84th Infantry assemble near Marche
//   move3-3  close (option 2), evening 24 Dec (night): Collins, Harmon; the First Army message (Montgomery + Hodges):
//            GO ON THE DEFENSIVE · YOU MAY FALL BACK to the Andenne - Hotton - Manhay line
//   move3-4  the choice FALL BACK vs ATTACK, Christmas Eve clock; stamp ATTACK AT DAWN
//   move3-5  25 Dec 08:00, dawn: CCB double envelopment of Celles, British tanks (UK flag) on the Meuse at Dinant / Foy, clear skies:
//            P-38s + Typhoons (glowing c47g symbol, locked K.bombRun with shake), the ring closes: IN THE BAG
//   move3-6  26-27 Dec: relief attacks from Rochefort beaten off, pocket destroyed; zoom out (option 1, 27 Dec): THE DEEPEST POINT
//   move3-7  casualty card (Cole, 2nd Armored 24-27 Dec) + COLLINS'S METHOD complete (3 lines)
// Fronts per date + sources: research/FACT_NOTES_ardennes.md; overlays + lines: tools/make_bulge_control.py (keep BULGE24/27 in sync).
// Built with: python3 tools/build_scene.py move3b ardennes_hd_ref move3-2 move3-7
const B = Battle();
const { at, P: PS } = B;
const END = B.T.duration;
const K = FXK(B);
const GG = GGK(B);
const PR = GG.proj(10, 133454, 87890);
const L = (lat, lon) => PR(lat, lon);
const FL = { us: "assets/media/us_flag_48star.png", uk: "assets/media/uk_flag.png", de: "assets/media/ger_reich_flag.png" };
// commander photos: licensed head shots from the photo agent (assets/media/<name>_head.png, CREDITS.md); initials show if a file is missing
const PHOTO = { collins: "assets/media/collins_head.png", harmon: "assets/media/harmon_head.png", monty: "assets/media/montgomery_head.png",
  lutt: "assets/media/luttwitz_head.png", white: "assets/media/white_head.png", hodges: "assets/media/hodges_head.png" };
// ---------- helpers (rokossovsky move3.js kit) ----------
const box = (txt, x, y, t, size = 16, until) => { SFX("ref:pop", t); return GG.pin(`<div style="background:#f1eee6;color:#111;font-family:Oswald;font-weight:500;letter-spacing:.28em;padding:${(size * 0.2).toFixed(1)}px ${(size * 0.35).toFixed(1)}px ${(size * 0.2).toFixed(1)}px ${(size * 0.6).toFixed(1)}px;font-size:${size}px;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.6)">${txt}</div>`, x, y, { t, until }); };
const town = (txt, lat, lon, t, o = {}) => { const [x, y] = L(lat, lon); B.city("", x, y, { r: o.r || 4, t, until: o.until }); return box(txt, x + (o.dx || 0), y + (o.dy != null ? o.dy : -18), t, o.size || 11, o.until); };
const flag = (src, name, x, y, t, until, w = 76) => GG.pin(`<div style="display:flex;flex-direction:column;align-items:center;gap:${(w * 0.05).toFixed(1)}px"><img src="${src}" style="width:${w}px;display:block;border:${Math.max(1, w / 60).toFixed(1)}px solid #1a1712;box-shadow:0 3px 8px rgba(0,0,0,0.55)"><div class="gg-lbl" style="position:relative;font-size:${(w / 4).toFixed(1)}px;color:#f7f3ea;text-shadow:0 2px 4px #000;letter-spacing:0.08em">${name}</div></div>`, x, y, { t, pop: true, until });
const unit = (id, side, lat, lon, icon, label, o = {}) => {
  const [x, y] = L(lat, lon), w = o.w || 22, h = o.h || 15;
  B.unit({ id, side, x, y, w, h, t: o.t, label });
  K.counter(id, { icon, flag: side === "rome" ? FL.de : (o.flag || "us"), size: o.size });
  const u = B.units[id]; u.el.querySelector(".blk").style.borderWidth = Math.max(1, w / 14).toFixed(1) + "px";
  const tg = u.el.querySelector(".tag"); if (tg) Object.assign(tg.style, { fontSize: (o.tag || 9) + "px", padding: "0 4px", marginTop: "2px" });
  if (o.until != null) B.hideUnits([id], o.until);
  return id;
};
const go = (id, t, dur, lat, lon, ease) => { const [x, y] = L(lat, lon); B.move(id, t, dur, x, y, ease || "power1.inOut"); };
const LL = (pts) => pts.map(([la, lo]) => L(la, lo));
const arw = (o) => { const g = B.arrow(o), w = o.width || 22, ps = g.querySelectorAll("path");   // casing scaled to the width
  ps[0].setAttribute("stroke-width", (w + Math.min(10, w * 0.6)).toFixed(1)); if (o.dash) ps[0].setAttribute("stroke-dasharray", o.dash);
  const hd = g.querySelector("polygon"); if (hd) hd.setAttribute("stroke-width", Math.min(5, w * 0.3).toFixed(1)); return g; };
const legend = (t, until, opt2) => GG.card(`<div style="display:flex;gap:26px;font-size:20px;letter-spacing:0.1em;align-items:center">${[["#2e5cb2", "#2c57b7", "ALLIES"], ["#be3a2a", "#bc2528", "GERMAN"]].map(([sq, ln, nm]) => `<span><b style="display:inline-block;width:20px;height:${opt2 ? 6 : 20}px;background:${opt2 ? ln : sq};${opt2 ? `box-shadow:0 0 8px ${ln};vertical-align:4px;` : "vertical-align:-3px;"}margin-right:8px;border:1px solid #f7f3ea"></b>${nm}</span>`).join("")}</div>`, "", 34, t, until);
const ctl = (state, t, until, dur = 1.0) => { const el = B.image(`assets/media/ard_ctl_${state}_mx.png`, 0, 0, 2880, 1620, { t, dur, until }); el.style.mixBlendMode = "multiply"; return el; };
const posOn = (pts, f) => { let Lt = 0; const seg = []; for (let j = 1; j < pts.length; j++) { const d = Math.hypot(pts[j][0] - pts[j - 1][0], pts[j][1] - pts[j - 1][1]); seg.push(d); Lt += d; }
  let d = f * Lt; for (let j = 0; j < seg.length; j++) { if (d <= seg[j]) { const a = pts[j], b = pts[j + 1], k = d / seg[j]; return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k]; } d -= seg[j]; }
  return pts[pts.length - 1]; };
// Allied fighter-bombers: the locked K.bombRun with the glowing C-47 symbol in blue; bombs on the track 0.25 s apart, shake on the first
const bomber = (pts, t, n = 4, dur = 4.0, size = 30) => {
  const bombs = []; for (let k = 0; k < n; k++) bombs.push(posOn(pts, (1.55 + k * 0.25) / dur).map((v, i) => v + (i ? (k % 2 ? 4 : -4) : 0)));
  K.bombRun({ kind: "c47g", side: "carth", size, alt: 9, dur, pts, t, bombs });
};
const badge = (o) => {   // K.badge + initials under the photo (shown if the photo file is missing) + the right flag in the ring
  const el = K.badge(o), ring = el.querySelector("div[style*='border-radius:50%']"), img = ring.querySelector("img");
  if (img) { const ini = document.createElement("div"); ini.style.cssText = "position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle, rgba(10,12,24,0.78) 0%, rgba(10,12,24,0.45) 100%);font-size:60px;font-weight:700;color:#f7f3ea;text-shadow:0 3px 6px #000";
    ini.textContent = o.initials || ""; ring.insertBefore(ini, img); img.onerror = () => { img.style.display = "none"; }; }
  return el;
};
const glowPath = (pts, col, w, t, until, pulses = 3) => {   // glowing stroke (Meuse, fall-back line), pulses then holds
  const p = document.createElementNS("http://www.w3.org/2000/svg", "path"), svg = document.getElementById("overlay");
  p.setAttribute("d", "M" + pts.map((q) => q.join(" ")).join(" L")); p.setAttribute("fill", "none"); p.setAttribute("stroke", col);
  p.setAttribute("stroke-width", w); p.setAttribute("stroke-linecap", "round"); p.setAttribute("stroke-linejoin", "round"); p.style.filter = `drop-shadow(0 0 ${w}px ${col})`;
  svg.insertBefore(p, svg.firstChild); gsap.set(p, { opacity: 0 });
  B.tl.to(p, { opacity: 0.95, duration: 0.5 }, t); if (pulses) B.tl.to(p, { opacity: 0.45, duration: 0.5, yoyo: true, repeat: pulses, ease: "sine.inOut" }, t + 0.5);
  if (until != null) B.tl.to(p, { opacity: 0, duration: 0.6 }, until); return p;
};
const scr = (html, css, t, until, from = { autoAlpha: 0, y: 30 }) => {   // screen-space element (above the map, under the credit)
  const el = document.createElement("div"); el.style.cssText = "position:absolute;" + css; el.innerHTML = html;
  document.getElementById("scene").insertBefore(el, document.getElementById("credit")); GG.hide(el);
  B.tl.fromTo(el, from, { autoAlpha: 1, y: 0, x: 0, duration: 0.5, ease: "power3.out" }, t); if (until != null) B.tl.to(el, { autoAlpha: 0, duration: 0.5 }, until); return el;
};
// fuel gauge (world pin): needle F -> E, red when empty
const gauge = (x, y, t, tEmpty, until, s = 1) => {
  const el = GG.pin(`<div style="display:flex;flex-direction:column;align-items:center;transform:scale(${s})"><svg width="64" height="40" viewBox="0 0 64 40" style="display:block;filter:drop-shadow(0 2px 3px rgba(0,0,0,.7))">
    <path d="M6 36 A26 26 0 0 1 58 36 Z" fill="rgba(18,16,12,0.9)" stroke="#f1eee6" stroke-width="2"/>
    <path class="arc" d="M10 34 A22 22 0 0 1 54 34" fill="none" stroke="#c9b48a" stroke-width="3" stroke-dasharray="3 3"/>
    <text x="9" y="30" font-family="Oswald" font-weight="700" font-size="9" fill="#e3232f">E</text><text x="50" y="30" font-family="Oswald" font-weight="700" font-size="9" fill="#f1eee6">F</text>
    <line class="ndl" x1="32" y1="35" x2="32" y2="13" stroke="#f1eee6" stroke-width="3" stroke-linecap="round"/><circle cx="32" cy="35" r="3.5" fill="#f1eee6"/></svg>
    <div style="font-family:Oswald;font-weight:700;font-size:10px;letter-spacing:.2em;color:#f1eee6;text-shadow:0 1px 3px #000;margin-top:1px">FUEL</div></div>`, x, y, { t, pop: true, until });
  const n = el.querySelector(".ndl"); gsap.set(n, { svgOrigin: "32 35", rotation: 62 });
  B.tl.to(n, { rotation: -66, duration: tEmpty - t - 0.4, ease: "power1.in" }, t + 0.4);
  B.tl.to(n, { attr: { stroke: "#e3232f" }, duration: 0.3 }, tEmpty - 0.1);
  for (let k = 0; k < 4; k++) SFX("tick", t + 0.5 + k * ((tEmpty - t - 0.6) / 4));
  return el;
};
const dimLine = (a, b, t, until, label, size = 10) => {   // measuring bracket between two points with a label
  const NS = "http://www.w3.org/2000/svg", svg = document.getElementById("overlay"), g = document.createElementNS(NS, "g");
  const dx = b[0] - a[0], dy = b[1] - a[1], Ln = Math.hypot(dx, dy), nx = -dy / Ln * 7, ny = dx / Ln * 7;
  g.innerHTML = `<path d="M${a[0]} ${a[1]} L${b[0]} ${b[1]} M${a[0] + nx} ${a[1] + ny} L${a[0] - nx} ${a[1] - ny} M${b[0] + nx} ${b[1] + ny} L${b[0] - nx} ${b[1] - ny}" stroke="rgba(0,0,0,.6)" stroke-width="5" fill="none" stroke-linecap="round"/>
    <path d="M${a[0]} ${a[1]} L${b[0]} ${b[1]} M${a[0] + nx} ${a[1] + ny} L${a[0] - nx} ${a[1] - ny} M${b[0] + nx} ${b[1] + ny} L${b[0] - nx} ${b[1] - ny}" stroke="#ffd54a" stroke-width="2.4" fill="none" stroke-linecap="round" stroke-dasharray="5 3"/>`;
  svg.appendChild(g); GG.hide(g); B.tl.fromTo(g, { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.4 }, t); if (until != null) B.tl.to(g, { autoAlpha: 0, duration: 0.5 }, until);
  const lab = GG.pin(`<div style="font-family:Oswald;font-weight:700;font-size:${size}px;letter-spacing:.14em;color:#111;background:#ffd54a;padding:1px 6px;box-shadow:0 2px 6px rgba(0,0,0,.6);white-space:nowrap">${label}</div>`, (a[0] + b[0]) / 2 - 3, (a[1] + b[1]) / 2 - 16, { t: t + 0.2, pop: true, until });
  SFX("hit", t + 0.25); return [g, lab];
};
